using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9: default discriminator property renamed from "Discriminator" to "$type".
            // Existing 500K documents use "Discriminator" — preserve the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9: id no longer includes discriminator (would generate "123" instead of "Product|123").
            // Existing documents have "Product|123" format — preserve it so point-reads still work.
            entity.HasRootDiscriminatorInJsonId(true);

            // EF Core 9: HasIndex now throws for Cosmos entities.
            // Manage indexing via Azure Portal / Bicep / Terraform instead.
            // REMOVED: entity.HasIndex(p => p.Sku);
        });
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } = null!; }

